WITH daily_brand AS ( SELECT cr.cr_returned_date_sk AS returned_date, i.i_brand AS brand, td.t_hour AS hour_of_day, COUNT(*) AS return_count, SUM(cr.cr_net_loss) AS daily_brand_net_loss FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN time_dim td ON cr.cr_returned_time_sk = td.t_time_sk WHERE td.t_hour BETWEEN 9 AND 17 GROUP BY cr.cr_returned_date_sk, i.i_brand, td.t_hour ) SELECT returned_date, brand, hour_of_day, daily_brand_net_loss, return_count, RANK() OVER (PARTITION BY returned_date ORDER BY daily_brand_net_loss DESC) AS loss_rank FROM daily_brand WHERE daily_brand_net_loss > 1000 ORDER BY returned_date, loss_rank
